from pathlib import Path
import base64,html,json,shutil,zipfile,hashlib
root=Path(__file__).resolve().parent.parent;art=Path('/workspace/artifacts');art.mkdir(exist_ok=True);qa=root/'qa/focus-google';stage=art/'Focus-google-20261026';stage.mkdir(exist_ok=True)
for directory in ['personal','development','source','validation']:
 target=stage/directory
 if target.exists():shutil.rmtree(target)
shutil.copytree(root/'focus-sync',stage/'personal');shutil.copytree(root/'focus-development',stage/'development');shutil.copytree(qa,stage/'validation');shutil.copytree(root/'qa/focus-three-screen',stage/'validation/three-screen')
source=stage/'source';source.mkdir()
for folder in ['web','scripts','focus-server','tests','drizzle','deploy']:shutil.copytree(root/folder,source/folder,ignore=shutil.ignore_patterns('__pycache__','*.pyc'))
for name in ['package.json','package-lock.json','.gitignore','FOCUS.md','FOCUS-SYNC.md','FOCUS-THREE-SCREEN.md','FOCUS-DEVELOPMENT.md','FOCUS-GOOGLE.md']:
 if (root/name).exists():shutil.copy2(root/name,source/name)
for name in ['FOCUS-SYNC.md','FOCUS-THREE-SCREEN.md','FOCUS-DEVELOPMENT.md','FOCUS-GOOGLE.md']:shutil.copy2(root/name,stage/name)
(stage/'README.md').write_text('# Focus Google連携テスト版\n\nNode.js 24でSTART-WINDOWS.cmdを開きます。実際のGoogle接続には初回のOAuth設定と認可が必要です。SETUP-GOOGLE-WINDOWS.cmdはGoogle Cloudで作成したウェブ用クライアントID・シークレットをローカル保存します。手順はFOCUS-GOOGLE.md。\n\n更新時は旧サーバーを閉じ、既存のfocus-data/を保持してpersonal/のコードを更新します。別フォルダへ移す場合は停止後にfocus-data/も引き継いでください。同じURL・ブラウザのIndexedDBはそのまま利用します。サイトデータは削除しません。\n\nGoogle APIだけを模擬して検証しています。実際のGoogleアカウントは未接続、共有HTTPS URLも未公開です。PC・iPhone共用には別途同期先が必要です。\n\n画面と検証.html、validation/REPORT.md、FOCUS-THREE-SCREEN.mdに操作と検証範囲を記載。開発用はSTART-DEVELOPMENT.cmdで別の保存領域を使います。秘密情報をチャットやGitに入れないでください。\n')
for name,folder,cmd in [('START-WINDOWS.cmd','personal','START-WINDOWS.cmd'),('START-DEVELOPMENT.cmd','development','START-WINDOWS.cmd'),('SETUP-GOOGLE-WINDOWS.cmd','personal','SETUP-GOOGLE-WINDOWS.cmd')]:
 (stage/name).write_bytes(('@echo off\r\ncd /d "%~dp0'+folder+'"\r\ncall '+cmd+'\r\n').encode())
def pic(name,alt):return '<img loading="lazy" alt="'+html.escape(alt)+'" src="data:image/png;base64,'+base64.b64encode((qa/name).read_bytes()).decode()+'">'
page=['''<!doctype html><html lang="ja"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Focus Google Calendar連携</title><style>body{margin:0;background:#10171c;color:#e7eeec;font:15px/1.8 system-ui,sans-serif}main{max-width:1100px;margin:auto;padding:24px}h1{font-size:26px}h2{font-size:21px;margin-top:34px}.note{padding:16px;border:1px solid #2b3b40;border-radius:12px;color:#c1d8d0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}figure{margin:0;padding:12px;background:#182228;border:1px solid #2b3b40;border-radius:12px}img{display:block;width:100%;max-height:800px;object-fit:contain;object-position:top}figcaption{font-size:13px;color:#a9c8bd;margin-bottom:12px}details{padding:14px;border:1px solid #2b3b40;border-radius:12px;margin:16px 0}summary{cursor:pointer}pre{white-space:pre-wrap;font:14px/1.8 system-ui;overflow-wrap:anywhere}a{color:#a9e3c9}table{border-collapse:collapse;width:100%;margin:24px 0}th,td{border-bottom:1px solid #2b3b40;padding:12px;text-align:left;vertical-align:top}@media(max-width:700px){main{padding:16px}.grid{grid-template-columns:1fr}th,td{font-size:13px;padding:8px}}</style><main><h1>Focus Google Calendar連携</h1><p>2026-10-26 · 独立テスト版 · 未公開</p><p class="note">実装・模擬API検証済みです。画像はすべて架空の予定。実際のGoogleアカウントは未接続です。初回に自分のOAuthクライアント設定とGoogleでの認可が必要です。</p><table><tr><th>Google → Focus</th><th>Focus → Google</th></tr><tr><td>複数カレンダーの予定・終日を表示。忙しい時間を避け、準備時間も含めて配置。</td><td>選んだカレンダーへタスク名・日時を反映。同一予定を増殖させず、Google側の編集は上書きしません。</td></tr></table><h2>日程</h2><p>9:00–10:00のGoogle予定を避け、準備10分を挟んで10:10–10:35へ配置する検証例です。Googleの予定は青、Focusのタスクは緑で区別。</p><div class="grid"><figure><figcaption>スマホ幅</figcaption>''',pic('dashboard-mobile.png','Google予定とFocusタスクを表示'),'</figure><figure><figcaption>PC幅</figcaption>',pic('dashboard-desktop.png','Google予定とFocusタスクをPCで表示'),'</figure></div><h2>設定</h2><div class="grid"><figure><figcaption>表示カレンダー・反映先・自動反映</figcaption>',pic('settings-mobile.png','Google連携設定スマホ'),'</figure><figure><figcaption>PCの設定</figcaption>',pic('settings-desktop.png','Google連携設定PC'),'</figure></div><h2>必要な初回設定</h2><p>Google CloudでCalendar APIとウェブ用OAuthクライアントを設定 → 付属の設定ツールへID・シークレットをローカル入力 → FocusでGoogleに接続 → 表示カレンダー・反映先を選択。</p><p>PC・iPhone共用には共有HTTPS URLも必要です。Google連携の認証はChatGPTから引き継ぎません。</p><details><summary>設定手順</summary><pre>',html.escape((root/'FOCUS-GOOGLE.md').read_text()),'</pre></details><details open><summary>検証結果と限界</summary><pre>',html.escape((qa/'REPORT.md').read_text()),'</pre></details></main></html>']
preview=art/'Focus-google-preview-20261026.html';preview.write_text(''.join(page));shutil.copy2(preview,stage/'画面と検証.html');shutil.copy2(root/'FOCUS-GOOGLE.md',art/'Focus-google-setup-20261026.md')
target=art/'Focus-google-20261026.zip'
with zipfile.ZipFile(target,'w',zipfile.ZIP_DEFLATED) as z:
 for f in sorted(stage.rglob('*')):
  if f.is_file():
   assert not f.name.endswith(('.sqlite','.sqlite-wal','.sqlite-shm')) and f.name not in ['sync-key.txt','server-config.json','google-config.json','google-token-key.txt','.env'],f
   z.write(f,'Focus/'+str(f.relative_to(stage)))
with zipfile.ZipFile(target) as z:assert z.testzip() is None
metadata={'file':target.name,'bytes':target.stat().st_size,'sha256':hashlib.sha256(target.read_bytes()).hexdigest(),'preview':preview.name};(art/'Focus-google-20261026-manifest.json').write_text(json.dumps(metadata,indent=2));print(json.dumps(metadata))
